import wandb, json

api = wandb.Api()
entity_project = 'xiaoyucorynne-/recovery_aware_struct_prune'

runs_info = {
    'grpo_standard_25': '6fclw4ro',
    'grpo_rasp_qwen_math_v3': 'yyg9ty4u',
    'grpo_standard_qwen_math_v3': '5n2snh48',
}

metrics_to_fetch = ['train/frac_reward_zero_std', 'train/grad_norm', 'train/reward']

for name, run_id in runs_info.items():
    run = api.run(f'{entity_project}/{run_id}')
    history = run.scan_history(keys=['_step'] + metrics_to_fetch)
    steps_data = []
    for row in history:
        entry = {'step': row.get('_step')}
        for m in metrics_to_fetch:
            entry[m] = row.get(m)
        if entry.get('train/frac_reward_zero_std') is not None:
            steps_data.append(entry)
    print(f'=== {name} ({run_id}, {run.state}) ===')
    for s in steps_data:
        print(f\"  step={s['step']}, frac={s['train/frac_reward_zero_std']}, grad={s['train/grad_norm']}, reward={s['train/reward']}\")
